   183|export function getSpecialistsForIntent(intentType: string, complexity: string): IVXSpecialistRole[] {
   184|  const roles: IVXSpecialistRole[] = [];
   185|
   186|  switch (intentType) {
   187|    case 'bug_fix':
   188|      roles.push('senior_developer', 'qa_engineer');
   189|      if (complexity === 'complex') roles.push('architect', 'security_engineer');
   190|      roles.push('proof_verifier');
   191|      break;
   192|    case 'feature':
   193|    case 'module':
   194|      roles.push('architect', 'senior_developer', 'qa_engineer');
   195|      if (complexity === 'complex') roles.push('security_engineer', 'devops_engineer');
   196|      roles.push('proof_verifier');
   197|      break;
   198|    case 'database':
   199|      roles.push('database_engineer', 'qa_engineer');
   200|      roles.push('proof_verifier');
   201|      break;
   202|    case 'deployment':
   203|      roles.push('devops_engineer');
   204|      roles.push('proof_verifier');
   205|      break;
   206|    case 'destructive':
   207|      roles.push('security_engineer', 'devops_engineer');
   208|      roles.push('proof_verifier');
   209|      break;
   210|    case 'business_analysis':
   211|    case 'investor_workflow':
   212|      roles.push('investor_analyst', 'product_analyst');
   213|      break;
   214|    case 'qa':
   215|      roles.push('qa_engineer', 'proof_verifier');
   216|      break;
   217|    default:
   218|      if (complexity === 'complex') roles.push('architect');
   219|      roles.push('senior_developer');
   220|      break;
   221|  }
   222|
   223|  // Always add response editor
   224|  roles.push('response_editor');
   225|
   226|  return roles;
