   445|// ─── Helper: Build Direct Answer ──────────────────────────────────
   446|
   447|function buildDirectAnswer(
   448|  input: IVXOrchestratorInput,
   449|  classification: ReturnType<typeof classifyRequest>,
   450|  verifiedMemory: Array<{ content: string; source: string; verified: boolean }>,
   451|  retrievalResult: { results: Array<{ source: string; content: string }> },
   452|  uncertainty: IVXUncertaintyStatus,
   453|  resolvedContext: string,
   454|): string {
   455|  // For simple questions, use memory + retrieved context
   456|  if (classification.complexity === 'simple') {
   457|    if (verifiedMemory.length > 0) {
   458|      return verifiedMemory[0].content;
   459|    }
   460|    if (retrievalResult.results.length > 0) {
   461|      return retrievalResult.results[0].content.slice(0, 500);
   462|    }
   463|    return 'I can help with that. Let me process your request.';
   464|  }
   465|
   466|  // For moderate+ complexity, summarize the plan
   467|  const parts: string[] = [];
   468|
   469|  if (resolvedContext) {
   470|    parts.push(`Referencing: ${resolvedContext.slice(0, 100)}`);
   471|  }
   472|
   473|  parts.push(`Intent: ${classification.intent} (${classification.complexity})`);
   474|  parts.push(`Model: ${classification.suggestedModel}`);
   475|  parts.push(`Uncertainty: ${uncertainty}`);
   476|
   477|  if (verifiedMemory.length > 0) {
   478|    parts.push(`Memory: ${verifiedMemory.length} verified records`);
   479|  }
   480|
   481|  if (classification.requiresApproval) {
   482|    parts.push('Owner approval required to execute.');
   483|  }
   484|
   485|  return parts.join('\n');
   486|}
